from pathlib import Path
import re,json
root=Path(__file__).resolve().parents[1]
# Source archive is optional; when rebuilding reference, point SOURCE_DIR at extracted originals.
import os
source=Path(os.environ.get('SOURCE_DIR',str(root.parent/'original/TAHA-CREATOR')))
rows=[]
for fn,role in [('bot.php','مدیریت مرکزی'),('Pedar.php','ربات اصلی'),('Haji.php','ربات فرزند')]:
 s=(source/fn).read_text();seen={}
 for m in re.finditer(r'\$text\s*==\s*"([^"\n]+)"',s):
  label=m.group(1);line=s.count('\n',0,m.start())+1
  if label in seen:seen[label]['lines'].append(line);continue
  after=s[m.end():m.end()+1800]
  step=re.search(r'step\([^,]+,\s*"([^"]+)"\)',after)
  row={'bot':role,'file':fn,'label':label,'lines':[line],'next_step':step.group(1) if step else ''}
  seen[label]=row;rows.append(row)
